package lint

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const generatedFixture = `/************************************
 * generated by the codegen package via 'boardgame-util codegen'
 * DO NOT EDIT by hand.
 ************************************/

package sample
`

func TestCheckGeneratedFile(t *testing.T) {
	dir := t.TempDir()
	expected := generatedFile{name: "auto_reader.go", contents: generatedFixture}

	diagnostic, stale := checkGeneratedFile("example/sample", dir, expected, false)
	if !stale || diagnostic.Code != CodeGenerated || !strings.Contains(diagnostic.Message, "missing") {
		t.Fatalf("missing check = (%+v, %v), want missing generated diagnostic", diagnostic, stale)
	}

	if diagnostic, stale := checkGeneratedFile("example/sample", dir, expected, true); stale {
		t.Fatalf("fix missing = (%+v, %v), want success", diagnostic, stale)
	}
	contents, err := os.ReadFile(filepath.Join(dir, expected.name))
	if err != nil || string(contents) != generatedFixture {
		t.Fatalf("fixed contents = (%q, %v), want generated fixture", contents, err)
	}

	if err := os.WriteFile(filepath.Join(dir, expected.name), []byte(generatedFixture+"// stale\n"), 0644); err != nil {
		t.Fatal(err)
	}
	if diagnostic, stale := checkGeneratedFile("example/sample", dir, expected, true); stale {
		t.Fatalf("fix stale = (%+v, %v), want success", diagnostic, stale)
	}

	if err := os.WriteFile(filepath.Join(dir, expected.name), []byte("package sample\n"), 0644); err != nil {
		t.Fatal(err)
	}
	diagnostic, stale = checkGeneratedFile("example/sample", dir, expected, true)
	if !stale || !strings.Contains(diagnostic.Message, "refusing") {
		t.Fatalf("fix creator-owned = (%+v, %v), want refusal", diagnostic, stale)
	}
}

func TestCheckGeneratedFileRemovesOwnedOrphan(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "auto_enum.go")
	if err := os.WriteFile(path, []byte(generatedFixture), 0644); err != nil {
		t.Fatal(err)
	}
	diagnostic, stale := checkGeneratedFile("example/sample", dir, generatedFile{name: "auto_enum.go"}, true)
	if stale {
		t.Fatalf("fix orphan = (%+v, %v), want success", diagnostic, stale)
	}
	if _, err := os.Stat(path); !os.IsNotExist(err) {
		t.Fatalf("orphan still exists: %v", err)
	}
}

func TestDeclaresNewDelegate(t *testing.T) {
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "main.go"), []byte("package sample\nfunc NewDelegate() int { return 0 }\n"), 0644); err != nil {
		t.Fatal(err)
	}
	found, err := declaresNewDelegate(dir)
	if err != nil || !found {
		t.Fatalf("declaresNewDelegate = (%v, %v), want (true, nil)", found, err)
	}
	if err := os.WriteFile(filepath.Join(dir, "main.go"), []byte("package sample\nfunc SomethingElse() {}\n"), 0644); err != nil {
		t.Fatal(err)
	}
	found, err = declaresNewDelegate(dir)
	if err != nil || found {
		t.Fatalf("declaresNewDelegate = (%v, %v), want (false, nil)", found, err)
	}
}

func TestCheckBundledGame(t *testing.T) {
	report := Check([]string{"../../../examples/pig"}, Options{})
	if !report.OK {
		t.Fatalf("Pig preflight failed: %+v", report.Diagnostics)
	}
	if len(report.Packages) != 1 || report.Packages[0] != "github.com/jkomoros/boardgame/examples/pig" {
		t.Fatalf("checked packages = %v, want Pig", report.Packages)
	}
}
